SEGMENTS = [
    # {
    #     "tracks": None,               # 1 — однопутный, 2 — двухпутный
    #     "max_speed_kmh": None,        # допустимая скорость на перегоне, км/ч
    #     "grade_permille": None,       # средний уклон, ‰ (+ подъём в направлении forward)
    #     "electrified": None,          # электрифицирован (True/False)
    #     "blocking": None,             # "auto" — автоблокировка, "semi_auto" — полуавтоматическая
    #     "wear": None,                 # износ пути 0..1 (множитель частоты дефектов рельсов)
    #     "flood_risk": None,           # множитель риска паводка/размыва (0 — нет риска)
    #     "snow_risk": None,            # множитель риска снежных заносов
    #     "sand_risk": None,            # множитель риска песчаных заносов
    #     "heat_risk": None,            # множитель риска температурного выброса пути
    #     "theft_risk": None,           # множитель риска хищений деталей пути
    #     "crossings_guarded": None,    # число переездов со шлагбаумом
    #     "crossings_unguarded": None,  # число переездов без шлагбаума
    # },
]

BLOCK_SECTION_KM = None  # длина блок-участка при автоблокировке, км

