# 5. УГРОЗЫ НА ПУТИ (дефекты, хищения, погода)
# ═══════════════════════════════════════════════════════════════════════════
# Частота: rate_per_100km_day * (длина/100) * множитель риска перегона.
# Множитель: rail_defect → "wear", theft → "theft_risk", flood → "flood_risk" и т.д.
#
# mean_duration_h:
#   для погоды (flood/snow/sand/heat) — длительность явления;
#   для rail_defect/theft — время ремонта после обнаружения.
# undetected_discovery_h — через сколько часов угрозу заметят, если датчики её не поймали
#   (обход, жалоба машиниста). Пока угроза не обнаружена, каждый проходящий поезд
#   рискует сойти с рельсов с вероятностью pass_incident_prob.
# После обнаружения вводится закрытие перегона (closure=True) или ограничение
#   скорости (speed_factor — доля от допустимой скорости, 0..1).
HAZARDS = {
    "rail_defect": {"rate_per_100km_day": None, "mean_duration_h": None,
                    "undetected_discovery_h": None, "pass_incident_prob": None,
                    "closure": None, "speed_factor": None},
    "theft":       {"rate_per_100km_day": None, "mean_duration_h": None,
                    "undetected_discovery_h": None, "pass_incident_prob": None,
                    "closure": None, "speed_factor": None},
    "flood":       {"rate_per_100km_day": None, "mean_duration_h": None,
                    "undetected_discovery_h": None, "pass_incident_prob": None,
                    "closure": None, "speed_factor": None},
    "snow":        {"rate_per_100km_day": None, "mean_duration_h": None,
                    "undetected_discovery_h": None, "pass_incident_prob": None,
                    "closure": None, "speed_factor": None},
    "sand":        {"rate_per_100km_day": None, "mean_duration_h": None,
                    "undetected_discovery_h": None, "pass_incident_prob": None,
                    "closure": None, "speed_factor": None},
    "heat":        {"rate_per_100km_day": None, "mean_duration_h": None,
                    "undetected_discovery_h": None, "pass_incident_prob": None,
                    "closure": None, "speed_factor": None},
}

